def clean(df):
    d = df.copy()

    # Normalize text columns: trim whitespace and fix known label variants.
    for col in d.columns:
        if d[col].dtype == object:
            d[col] = d[col].astype("string").str.strip()

    if "species" in d.columns:
        d["species"] = d["species"].replace({"Adeile": "Adelie"})

    if "island" in d.columns:
        d["island"] = d["island"].replace({"Torgersen": "Torgersen", "Biscoe": "Biscoe", "Dream": "Dream"})

    if "sex" in d.columns:
        d["sex"] = d["sex"].str.lower()
        d["sex"] = d["sex"].replace({"m": "male", "f": "female"})

    # Ensure numeric measurement columns are numeric.
    for col in ["bill_length_mm", "bill_depth_mm", "flipper_length_mm", "body_mass_g", "year"]:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors="coerce")

    # Correct an obvious body-mass unit error, e.g. 4,850,000 g -> 4,850 g.
    if "body_mass_g" in d.columns:
        too_large = d["body_mass_g"] > 6500
        corrected = d.loc[too_large, "body_mass_g"] / 1000.0
        valid = corrected.between(2500, 6500)
        d.loc[corrected[valid].index, "body_mass_g"] = corrected[valid]

    # Remove exact duplicate rows so each measured penguin is counted once.
    d = d.drop_duplicates()

    return d


def answer(df):
    d = clean(df)
    d = d.dropna(subset=["island"])
    counts = d.groupby("island", sort=False).size()
    return {str(k): int(v) for k, v in counts.items()}
